#pragma once
// The built-in vocabulary. The data lives in dsp/src/words_generated.cpp,
// which is generated by `make words` from tools/words.txt.

#include <cstdint>

namespace cvspeak {

struct LpcWord {
    const char* name;
    const uint8_t* data;  // lpc_format.h bitstream, ends with a stop frame
    uint16_t bytes;
    uint16_t frames;
    float medianPeriod;   // median voiced pitch period, in 8 kHz samples
};

extern const LpcWord kWords[];
extern const int kNumWords;

}  // namespace cvspeak
